columnWidth = Generators.observe(notify =&gt; {
  const textCol = d3.select('.text-column').node();
  if (!textCol) return notify(width * 0.45);

  const ro = new ResizeObserver(() =&gt; {
    notify(textCol.getBoundingClientRect().width * .9);
  });
  ro.observe(textCol);
  notify(textCol.getBoundingClientRect().width * .9);

  return () =&gt; ro.disconnect();
});

